        def do_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            nonlocal tx_changes, tx_total, tx_trigger, tx_other_total, tx_other_trigger
            store = main if conn == 'main' else other
            existed = key in store
            if put_mode == 'ignore':
                if existed:
                    changed = 0
                else:
                    store[key] = value
                    changed = 1
            elif put_mode == 'replace':
                store[key] = value
                changed = 1
            else:
